using XPlaneLocalizerFixer.Parsers;

namespace XPlaneLocalizerFixer.Tests.Parsers;

public class AptDatParserTest
{
    [Fact]
    public void Parse_WhenAirportHeaderExists_CreatesAirport()
    {
        // Arrange
        string[] lines =
        [
            "A",
            "1200 Generated by WorldEditor 2.7.3-r1 / TY mode",
            "1     26 0 0 VHHH Hong Kong Intl",
            "1302 city Hong Kong",
            "1302 country CHN",
            "1302 datum_lat 22.309",
            "1302 datum_lon 113.915",
            "1302 gui_label 2D",
            "100 60.05 37 837 0.25 1 3 0 07L 22.3210589 113.8807015 173 298 7 2 1 2 25R 22.3322770 113.9155974 174 297 7 2 1 2",
            "99"
        ];

        var parser = new AptDatParser();

        // Act
        var airports = parser.Parse(lines);

        // Assert
        var airport = Assert.Single(airports);

        Assert.Equal("VHHH", airport.Identifier);
        Assert.Equal("Hong Kong Intl", airport.Name);
    }

    [Fact]
    public void Parse_WhenRunwayRecordExists_ParsesCoordinatesCorrectly()
    {
        // Arrange
        string[] lines =
        [
            "1 26 0 0 VHHH Hong Kong Intl",
            "100 60.05 37 837 0.25 1 3 0 07L 22.3210589 113.8807015 173 298 7 2 1 2 25R 22.3322770 113.9155974 174 297 7 2 1 2"
        ];

        var parser = new AptDatParser();

        // Act
        var airports = parser.Parse(lines);

        // Assert
        var airport = Assert.Single(airports);

        Assert.Equal("VHHH", airport.Identifier);
        Assert.Equal(2, airport.Runways.Count);

        var runway07L = Assert.Single(
            airport.Runways,
            runway => runway.Identifier == "07L");

        var runway25R = Assert.Single(
            airport.Runways,
            runway => runway.Identifier == "25R");

        Assert.Equal(22.3210589, runway07L.StartPosition.Latitude);
        Assert.Equal(113.8807015, runway07L.StartPosition.Longitude);
        Assert.Equal(22.3322770, runway07L.EndPosition.Latitude);
        Assert.Equal(113.9155974, runway07L.EndPosition.Longitude);

        Assert.Equal(22.3322770, runway25R.StartPosition.Latitude);
        Assert.Equal(113.9155974, runway25R.StartPosition.Longitude);
        Assert.Equal(22.3210589, runway25R.EndPosition.Latitude);
        Assert.Equal(113.8807015, runway25R.EndPosition.Longitude);
    }

    [Fact]
    public void Parse_WhenMultipleAirportsExist_AssignsRunwaysCorrectly()
    {
        // Arrange
        string[] lines =
        [
            "1 26 0 0 VHHH Hong Kong Intl",
            "100 60.05 37 837 0.25 1 3 0 07L 22.3210589 113.8807015 173 298 7 2 1 2 25R 22.3322770 113.9155974 174 297 7 2 1 2",

            "1     23 0 0 SBGL Rio de Janeiro - Galeão Intl",
            "100 50.00 2 1 0.15 1 3 0  10 -22.8018460 -43.2552180 0 0 3 0 1 1 28 -22.7921711 -43.2176336 0 0 3 1 0 1",

            "99"
        ];

        var parser = new AptDatParser();

        // Act
        var airports = parser.Parse(lines);

        // Assert
        Assert.Equal(2, airports.Count);

        var vhhh = Assert.Single(
            airports,
            airport => airport.Identifier == "VHHH");

        var sbgl = Assert.Single(
            airports,
            airport => airport.Identifier == "SBGL");

        Assert.Equal(2, vhhh.Runways.Count);
        Assert.Equal(2, sbgl.Runways.Count);

        Assert.Contains(vhhh.Runways, runway => runway.Identifier == "07L");
        Assert.Contains(vhhh.Runways, runway => runway.Identifier == "25R");

        Assert.Contains(sbgl.Runways, runway => runway.Identifier == "10");
        Assert.Contains(sbgl.Runways, runway => runway.Identifier == "28");

        Assert.DoesNotContain(vhhh.Runways, runway => runway.Identifier == "10");
        Assert.DoesNotContain(sbgl.Runways, runway => runway.Identifier == "07L");
    }

    [Fact]
    public void Parse_WhenIcaoMetadataExists_UsesIcaoCode()
    {
        // Arrange
        string[] lines =
        [
            "1 26 0 0 VHHH Hong Kong Intl",
            "1302 icao_code VHHH",
            "100 60.05 37 837 0.25 1 3 0 07L 22.3210589 113.8807015 173 298 7 2 1 2 25R 22.3322770 113.9155974 174 297 7 2 1 2",
            "99"
        ];

        var parser = new AptDatParser();

        // Act
        var airports = parser.Parse(lines);

        // Assert
        var airport = Assert.Single(airports);

        Assert.Equal("VHHH", airport.Identifier);
        Assert.Equal("VHHH", airport.IcaoCode);
        Assert.Equal(2, airport.Runways.Count);
    }

    [Fact]
    public void Parse_WhenRunwayRecordIsIncomplete_ThrowsFormatException()
    {
        // Arrange
        string[] lines =
        [
            "1 26 0 0 VHHH Hong Kong Intl",
            "100 60.05 37 837 0.25 1 3 0 07L 22.3210589 113.8807015",
            "99"
        ];

        var parser = new AptDatParser();

        // Act
        var exception = Assert.Throws<FormatException>(() => parser.Parse(lines));

        // Assert
        Assert.Contains("Invalid runway record", exception.Message);
        Assert.Contains("line 2", exception.Message);
    }
}